values ('9f613b6e-1e0b-4bad-b222-81fac291565f', '70fd6c98-17f2-4e56-be6c-cea7055fb759', 'Leadership strategy wellness', 2, '', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross-wellness_leadership-strategy-wellness-activity-7442480422464253952-bu4R?utm_source=share&utm_medium=member_desktop&rcm=ACoAACKi8XsB9WBoWK1z6g7nRgrBaW3-4QoyJT8', 'posted', '2026-03-25T09:00:00Z', '2026-03-25T09:00:00Z');
