values ('d6c18ef9-fb49-4d35-81b3-79a6680c714d', '70fd6c98-17f2-4e56-be6c-cea7055fb759', 'Inmycorner case study', 18, '', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross-wellness_inmycorner-case-study-activity-7455496262864257024-_Fei?utm_source=share&utm_medium=member_desktop&rcm=ACoAACKi8XsB9WBoWK1z6g7nRgrBaW3-4QoyJT8', 'posted', '2026-04-30T09:00:00Z', '2026-04-30T09:00:00Z');
